INSERT INTO creators (id, slug, name, source, published, catalog_hash, created_at, updated_at) VALUES ('autostacc', 'autostacc', 'AutoStacc', 'catalog', 1, 'c53e5f786a58ae5c', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'))
  ON CONFLICT (id) DO UPDATE SET slug = excluded.slug, name = excluded.name, source = excluded.source, published = excluded.published, catalog_hash = excluded.catalog_hash, deleted_at = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE creators.source = 'catalog' AND (creators.catalog_hash IS NOT excluded.catalog_hash OR creators.deleted_at IS NOT NULL);
UPDATE creators SET published = 0, deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE source = 'catalog' AND deleted_at IS NULL AND id NOT IN ('autostacc');
